package com.campusnova.knowledge;
import com.campusnova.model.*; import com.campusnova.repository.*; import com.campusnova.service.SemanticTextService; import org.springframework.stereotype.Component; import java.util.*;
@Component public class DatabaseKnowledgeSource implements KnowledgeSource { private final FaqRepository faqs; private final AnnouncementRepository announcements; private final SemanticTextService semantic; public DatabaseKnowledgeSource(FaqRepository f,AnnouncementRepository a,SemanticTextService s){faqs=f;announcements=a;semantic=s;} public List<KnowledgeDocument> findRelevant(String q,Collection<String> memory){List<KnowledgeDocument> all=new ArrayList<KnowledgeDocument>();for(Faq f:faqs.findByActiveTrue())all.add(new KnowledgeDocument("FAQ: "+f.getQuestion(),f.getCategory().getName(),f.getQuestion()+"\n"+f.getAnswer()+"\n"+f.getKeywords(),false));for(Announcement a:announcements.findAll())all.add(new KnowledgeDocument("Announcement: "+a.getTitle(),"Announcements",a.getTitle()+"\n"+a.getBody(),false));Collections.sort(all,new Comparator<KnowledgeDocument>(){public int compare(KnowledgeDocument a,KnowledgeDocument b){return Double.compare(semantic.score(q,memory,b.getContent()),semantic.score(q,memory,a.getContent()));}});List<KnowledgeDocument> result=new ArrayList<KnowledgeDocument>();for(KnowledgeDocument d:all)if(semantic.score(q,memory,d.getContent())>=.12&&result.size()<4)result.add(d);return result;} }
